import{_ as t,o as s,c as o,ag as a}from"./chunks/framework.DoUXNnsN.js";const g=JSON.parse('{"title":"PowerShell","description":"","frontmatter":{"title":"PowerShell","aliases":["PowerShell 5.1","PowerShell 7","pwsh","Windows PowerShell","PS","对象管道","执行策略","ExecutionPolicy"],"tags":["工具与工程","命令行","PowerShell","Windows"],"status":"ai-draft","sources":["https://learn.microsoft.com/en-us/powershell/scripting/whats-new/differences-from-windows-powershell","https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_execution_policies","https://learn.microsoft.com/en-us/powershell/scripting/overview","基于模型知识"],"updated":"2026-10-21T00:00:00.000Z","order":8},"headers":[],"relativePath":"50-工具与工程/PowerShell.md","filePath":"50-工具与工程/PowerShell.md"}'),n={name:"50-工具与工程/PowerShell.md"};function d(c,e,i,l,p,r){return s(),o("div",null,[...e[0]||(e[0]=[a(`<blockquote><p>本篇的命令都在本机 <strong>Windows PowerShell 5.1.26100</strong>（<code>$PSVersionTable.PSEdition</code> 为 <code>Desktop</code>）里实际运行过，输出是真实的（文件大小等为本次实验数据）。<strong>本机没有安装 PowerShell 7（<code>pwsh</code>）</strong>，所以&quot;5.1 与 7 的区别&quot;一节只依据微软官方文档，未在本机验证，已登记待核对。</p></blockquote><blockquote><p>读完你应该能：说清 PowerShell 和 cmd、Bash 的最大区别（管道传对象）；用 <code>Get-Process</code>、<code>Where-Object</code>、<code>Select-Object</code> 等写出筛选、排序、统计的一行命令；理解执行策略报错并安全处理；知道 5.1 与 7 的区别。</p></blockquote><h2 id="一句话定义" tabindex="-1">一句话定义 <a class="header-anchor" href="#一句话定义" aria-label="Permalink to &quot;一句话定义&quot;">​</a></h2><p><strong>PowerShell</strong> 是微软的命令行 Shell 和脚本语言，它的核心特色是：命令之间通过管道传递的不是文本，而是带属性和方法的 <strong>.NET 对象</strong>。</p><h2 id="先修知识" tabindex="-1">先修知识 <a class="header-anchor" href="#先修知识" aria-label="Permalink to &quot;先修知识&quot;">​</a></h2><ul><li><a href="/Encyclopedia/50-工具与工程/命令行与Linux">命令行与Linux</a>：知道命令、选项、管道 <code>|</code> 的概念。</li><li><a href="/Encyclopedia/20-编程语言/CSharp/CSharp类型与变量">CSharp类型与变量</a>：PowerShell 的对象就是 .NET 对象，了解&quot;属性&quot;&quot;方法&quot;会更容易理解。</li></ul><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>在 <a href="/Encyclopedia/50-工具与工程/命令行与Linux">命令行与Linux</a> 里我们用 <code>grep</code>、<code>sed</code>、<code>cut</code> 这类工具处理<strong>文本</strong>。文本管道有个天然的麻烦：想取&quot;第 5 列&quot;就得靠空格分隔、靠正则，输出格式一变脚本就坏。</p><p>Windows 的世界里，进程、服务、注册表、文件，在系统里本来就是有结构的对象。PowerShell 的做法是：命令输出<strong>对象</strong>，下一个命令直接用对象的属性——&quot;取 <code>Length</code> 属性大于 200 的&quot;，而不是&quot;切第 3 列看数字&quot;。</p><p>类比：文本管道像在流水线上传<strong>照片</strong>，下一站要自己重新识别照片里的内容；对象管道是直接传<strong>实物</strong>，下一站可以直接量尺寸、称重。</p><p>Windows 运维、软件部署脚本、批量管理服务器、CI 流程里的 Windows 任务，都常用 PowerShell。</p><h2 id="核心概念" tabindex="-1">核心概念 <a class="header-anchor" href="#核心概念" aria-label="Permalink to &quot;核心概念&quot;">​</a></h2><h3 id="命令的命名-动词-名词" tabindex="-1">命令的命名：动词-名词 <a class="header-anchor" href="#命令的命名-动词-名词" aria-label="Permalink to &quot;命令的命名：动词-名词&quot;">​</a></h3><p>PowerShell 的命令叫 <strong>cmdlet</strong>（读作 command-let），统一为 <code>动词-名词</code>：<code>Get-Process</code>（获取进程）、<code>Stop-Process</code>、<code>Get-ChildItem</code>（列目录下的内容）、<code>Set-Location</code>（切换目录）。好处是可以猜：想&quot;获取服务&quot;？<code>Get-Service</code>。</p><p>为了使用方便，常用命令有<strong>别名</strong>：<code>ls</code>、<code>dir</code> 都是 <code>Get-ChildItem</code> 的别名，<code>cd</code> 是 <code>Set-Location</code>，<code>cat</code> 是 <code>Get-Content</code>。本机实测 <code>Get-Alias ls</code> 确认其指向 <code>Get-ChildItem</code>。注意：这些别名只是名字像 Linux 命令，参数和行为<strong>不一样</strong>，<code>ls -l</code> 在 PowerShell 里会报错。</p><p>要查某个命令怎么用：<code>Get-Help Get-Process</code>，或 <code>Get-Command *service*</code> 搜索命令名。</p><h3 id="对象管道" tabindex="-1">对象管道 <a class="header-anchor" href="#对象管道" aria-label="Permalink to &quot;对象管道&quot;">​</a></h3><p>执行 <code>Get-ChildItem a.log</code> 返回的是一个 <code>System.IO.FileInfo</code> 对象（本机用 <code>.GetType().FullName</code> 验证）。它有 <code>Name</code>、<code>Length</code>、<code>CreationTime</code> 等<strong>属性</strong>。查看一个对象有哪些属性：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; Get-ChildItem a.log | Get-Member -MemberType Property</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Name            Definition</span></span>
<span class="line"><span>----            ----------</span></span>
<span class="line"><span>Attributes      System.IO.FileAttributes Attributes {get;set;}</span></span>
<span class="line"><span>CreationTime    datetime CreationTime {get;set;}</span></span>
<span class="line"><span>CreationTimeUtc datetime CreationTimeUtc {get;set;}</span></span>
<span class="line"><span>Directory       System.IO.DirectoryInfo Directory {get;}</span></span>
<span class="line"><span>DirectoryName   string DirectoryName {get;}</span></span></code></pre></div><p>（只截取前 5 行。）<code>Get-Member</code> 是学 PowerShell 最重要的命令：<strong>不知道能取什么属性时，就 <code>| Get-Member</code></strong>。</p><h3 id="四个最常用的-管道工具" tabindex="-1">四个最常用的&quot;管道工具&quot; <a class="header-anchor" href="#四个最常用的-管道工具" aria-label="Permalink to &quot;四个最常用的&quot;管道工具&quot;&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>别名</th><th>作用</th><th>类比 SQL</th></tr></thead><tbody><tr><td><code>Where-Object</code></td><td><code>where</code>、<code>?</code></td><td>按条件<strong>筛选</strong>对象</td><td><code>WHERE</code></td></tr><tr><td><code>Select-Object</code></td><td><code>select</code></td><td><strong>选取</strong>属性或前几个</td><td><code>SELECT</code> / <code>TOP</code></td></tr><tr><td><code>Sort-Object</code></td><td><code>sort</code></td><td><strong>排序</strong></td><td><code>ORDER BY</code></td></tr><tr><td><code>Group-Object</code></td><td><code>group</code></td><td><strong>分组</strong>计数</td><td><code>GROUP BY</code></td></tr><tr><td><code>Measure-Object</code></td><td><code>measure</code></td><td>求和、平均、计数</td><td>聚合函数</td></tr><tr><td><code>ForEach-Object</code></td><td><code>foreach</code>、<code>%</code></td><td>对每个对象执行代码块</td><td>循环</td></tr></tbody></table><p>在 <code>{ }</code> 代码块里，<strong><code>$_</code> 代表管道中当前的这个对象</strong>。</p><h3 id="比较运算符" tabindex="-1">比较运算符 <a class="header-anchor" href="#比较运算符" aria-label="Permalink to &quot;比较运算符&quot;">​</a></h3><p>PowerShell 不用 <code>&gt;</code>、<code>&lt;</code>（它们是重定向符号），而用<strong>以连字符开头的字母运算符</strong>：</p><table tabindex="0"><thead><tr><th>运算符</th><th>含义</th></tr></thead><tbody><tr><td><code>-eq</code> / <code>-ne</code></td><td>等于 / 不等于</td></tr><tr><td><code>-gt</code> / <code>-ge</code></td><td>大于 / 大于等于</td></tr><tr><td><code>-lt</code> / <code>-le</code></td><td>小于 / 小于等于</td></tr><tr><td><code>-like</code></td><td>通配符匹配（<code>*</code>、<code>?</code>）</td></tr><tr><td><code>-match</code></td><td>正则匹配</td></tr><tr><td><code>-and</code> / <code>-or</code> / <code>-not</code></td><td>逻辑</td></tr></tbody></table><h3 id="变量与环境变量" tabindex="-1">变量与环境变量 <a class="header-anchor" href="#变量与环境变量" aria-label="Permalink to &quot;变量与环境变量&quot;">​</a></h3><p>变量以 <code>$</code> 开头：<code>$x = 5</code>。环境变量通过 <code>$env:</code> 前缀访问：<code>$env:USERNAME</code>、<code>$env:PATH</code>。详见 <a href="/Encyclopedia/50-工具与工程/环境变量与PATH">环境变量与PATH</a>。</p><h3 id="执行策略-execution-policy" tabindex="-1">执行策略（Execution Policy） <a class="header-anchor" href="#执行策略-execution-policy" aria-label="Permalink to &quot;执行策略（Execution Policy）&quot;">​</a></h3><p>新手第一次运行 <code>.ps1</code> 脚本最常见的拦路虎。<strong>执行策略</strong>是 PowerShell 控制&quot;能不能运行脚本&quot;的一项安全设置。微软文档的取值：</p><table tabindex="0"><thead><tr><th>策略</th><th>含义</th></tr></thead><tbody><tr><td><code>Restricted</code></td><td>只能执行单条命令，<strong>不允许运行任何脚本</strong></td></tr><tr><td><code>RemoteSigned</code></td><td>本机编写的脚本可以运行；<strong>从网上下载的</strong>脚本必须有可信发布者的数字签名（或已解除锁定）。Windows 服务器默认</td></tr><tr><td><code>AllSigned</code></td><td>所有脚本都必须签名</td></tr><tr><td><code>Unrestricted</code></td><td>都能运行，对来自网络的会警告</td></tr><tr><td><code>Bypass</code></td><td>什么都不拦，也不提示</td></tr><tr><td><code>Undefined</code></td><td>该范围未设置</td></tr></tbody></table><p>按**范围（Scope）**设置，优先级从高到低：<code>MachinePolicy</code>（组策略）、<code>UserPolicy</code>（组策略）、<code>Process</code>（仅当前会话）、<code>CurrentUser</code>、<code>LocalMachine</code>。所有范围都是 <code>Undefined</code> 时，Windows 客户端的生效策略是 <code>Restricted</code>，Windows Server 上是 <code>RemoteSigned</code>。</p><p>查看（本机实测输出）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; Get-ExecutionPolicy -List</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        Scope ExecutionPolicy</span></span>
<span class="line"><span>        ----- ---------------</span></span>
<span class="line"><span>MachinePolicy       Undefined</span></span>
<span class="line"><span>   UserPolicy       Undefined</span></span>
<span class="line"><span>      Process          Bypass     &lt;-- 因为我用 -ExecutionPolicy Bypass 启动了这次会话</span></span>
<span class="line"><span>  CurrentUser       Undefined</span></span>
<span class="line"><span> LocalMachine    RemoteSigned</span></span></code></pre></div><p>微软特别说明：执行策略<strong>不是安全边界</strong>，只是帮用户避免误操作的&quot;纵深防御&quot;——用户把脚本内容直接敲进命令行就能绕过。所以别把它当成防黑客的工具，也别为了图省事全局设成 <code>Bypass</code>。</p><h3 id="windows-powershell-5-1-与-powershell-7-的区别-据官方文档-⚠-本机未验证" tabindex="-1">Windows PowerShell 5.1 与 PowerShell 7 的区别（据官方文档，⚠ 本机未验证） <a class="header-anchor" href="#windows-powershell-5-1-与-powershell-7-的区别-据官方文档-⚠-本机未验证" aria-label="Permalink to &quot;Windows PowerShell 5.1 与 PowerShell 7 的区别（据官方文档，⚠ 本机未验证）&quot;">​</a></h3><table tabindex="0"><thead><tr><th></th><th>Windows PowerShell 5.1</th><th>PowerShell 7.x</th></tr></thead><tbody><tr><td>可执行文件</td><td><code>powershell.exe</code></td><td><code>pwsh.exe</code>（官方：改名是为了可以和 5.1 并存）</td></tr><tr><td>基于</td><td>.NET Framework 4.5</td><td>.NET Core / 现代 .NET（如 7.6 基于 .NET 10，7.4 基于 .NET 8，均为 LTS）</td></tr><tr><td>平台</td><td>仅 Windows，随系统自带</td><td>Windows、macOS、Linux，需单独安装，与 5.1 <strong>并存</strong></td></tr><tr><td>管道链操作符 <code>&amp;&amp;</code>、<code>||</code></td><td>不支持</td><td>支持</td></tr><tr><td>空值合并 <code>??</code>、<code>??=</code></td><td>不支持</td><td>支持（官方文档列出）</td></tr><tr><td><code>$OutputEncoding</code> 默认</td><td>ASCII</td><td>UTF-8 无 BOM（官方文档）</td></tr><tr><td>被移除的内容</td><td>—</td><td>如 PowerShell Workflow 等依赖 .NET Framework 的特性</td></tr></tbody></table><p>实践建议：Windows 上的<strong>系统自带脚本</strong>用 5.1（每台 Windows 都有），自己的新工具可以用 7。写给别人用的脚本要注明依赖的版本。</p><h2 id="逐步例子" tabindex="-1">逐步例子 <a class="header-anchor" href="#逐步例子" aria-label="Permalink to &quot;逐步例子&quot;">​</a></h2><p>先在 <code>%TEMP%\\pslab</code> 建三个文件：<code>a.log</code>（100 个字符）、<code>b.log</code>（3000 个字符）、<code>c.txt</code>（500 个字符）。<code>Set-Content</code> 会在末尾加一个换行（2 字节），所以实际大小是 102、3002、502。以下均为本机实际输出。</p><p><strong>1. 列出文件，只看名字和大小</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; Get-ChildItem | Select-Object Name, Length</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Name  Length</span></span>
<span class="line"><span>----  ------</span></span>
<span class="line"><span>a.log    102</span></span>
<span class="line"><span>b.log   3002</span></span>
<span class="line"><span>c.txt    502</span></span></code></pre></div><p><strong>2. 筛选：大于 200 字节的文件</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; Get-ChildItem | Where-Object { $_.Length -gt 200 } | Select-Object Name, Length</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Name  Length</span></span>
<span class="line"><span>----  ------</span></span>
<span class="line"><span>b.log   3002</span></span>
<span class="line"><span>c.txt    502</span></span></code></pre></div><p><code>$_.Length -gt 200</code> 的意思是&quot;当前对象的 Length 属性大于 200&quot;。简化写法（PowerShell 3.0 起）：<code>Where-Object Length -gt 200</code>。</p><p><strong>3. 只要名字这一个值（而不是带表头的表格）</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; Get-ChildItem | Where-Object Length -gt 200 | Select-Object -ExpandProperty Name</span></span>
<span class="line"><span>b.log</span></span>
<span class="line"><span>c.txt</span></span></code></pre></div><p><code>-ExpandProperty</code> 把属性&quot;展开&quot;成纯值，后续命令才好使用。</p><p><strong>4. 排序取前 N</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; Get-ChildItem | Sort-Object Length -Descending | Select-Object -First 2 Name, Length</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Name  Length</span></span>
<span class="line"><span>----  ------</span></span>
<span class="line"><span>b.log   3002</span></span>
<span class="line"><span>c.txt    502</span></span></code></pre></div><p><strong>5. 按扩展名分组计数</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; Get-ChildItem | Group-Object Extension | Select-Object Name, Count</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Name Count</span></span>
<span class="line"><span>---- -----</span></span>
<span class="line"><span>.log     2</span></span>
<span class="line"><span>.txt     1</span></span></code></pre></div><p><strong>6. 统计</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; Get-ChildItem | Measure-Object Length -Sum -Average | Select-Object Count, Sum, Average</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Count  Sum Average</span></span>
<span class="line"><span>-----  --- -------</span></span>
<span class="line"><span>    3 3606    1202</span></span></code></pre></div><p>校验：102 + 3002 + 502 = 3606，3606 ÷ 3 = 1202。</p><p><strong>7. 计算属性：自己造一列（换算成 KB）</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; Get-ChildItem | Select-Object Name, @{n=&#39;KB&#39;; e={ [math]::Round($_.Length/1KB, 2) }}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Name    KB</span></span>
<span class="line"><span>----    --</span></span>
<span class="line"><span>a.log  0.1</span></span>
<span class="line"><span>b.log 2.93</span></span>
<span class="line"><span>c.txt 0.49</span></span></code></pre></div><p><code>@{n=&#39;KB&#39;; e={...}}</code> 中 <code>n</code> 是新列名，<code>e</code> 是计算表达式。<code>1KB</code> 是 PowerShell 内置的 1024。校验：3002/1024 = 2.931…→2.93。</p><p><strong>8. 一键变成 JSON</strong>（对象的好处：想要什么格式都行，见 <a href="/Encyclopedia/50-工具与工程/JSON-XML-YAML">JSON-XML-YAML</a>）</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; Get-ChildItem *.log | Select-Object Name, Length | ConvertTo-Json</span></span>
<span class="line"><span>[</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;Name&quot;:  &quot;a.log&quot;,</span></span>
<span class="line"><span>        &quot;Length&quot;:  102</span></span>
<span class="line"><span>    },</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        &quot;Name&quot;:  &quot;b.log&quot;,</span></span>
<span class="line"><span>        &quot;Length&quot;:  3002</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>]</span></span></code></pre></div><p><strong>9. 进程：按内存排序</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; Get-Process | Sort-Object WorkingSet64 -Descending | Select-Object -First 3 Name, Id, WorkingSet64</span></span></code></pre></div><p><code>Get-Process</code> 返回的每个对象有 <code>Id</code>、<code>ProcessName</code>、<code>WorkingSet64</code>（占用的物理内存，字节）等属性——本机用 <code>Get-Member</code> 确认过。输出内容因机器而异，这里不贴。结束某个进程：<code>Get-Process -Name notepad | Stop-Process</code>。</p><p><strong>10. 处理错误</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PS&gt; try { Get-Item .\\nonexist.txt -ErrorAction Stop } catch { &quot;caught: &quot; + $_.Exception.GetType().Name }</span></span>
<span class="line"><span>caught: ItemNotFoundException</span></span></code></pre></div><p>PowerShell 的很多错误是&quot;非终止错误&quot;，会打印红字但脚本继续；加 <code>-ErrorAction Stop</code> 把它变成终止错误，才能被 <code>try/catch</code> 捕获。</p><p><strong>11. 执行策略的真实表现</strong></p><p>写一个 <code>hi.ps1</code>，内容 <code>Write-Output &quot;hi from script&quot;</code>，分别用两种策略启动一个新的 PowerShell 运行它（本机实测）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&gt; powershell -NoProfile -ExecutionPolicy RemoteSigned -File hi.ps1</span></span>
<span class="line"><span>hi from script</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&gt; powershell -NoProfile -ExecutionPolicy Restricted -File hi.ps1</span></span>
<span class="line"><span>（报错：禁止在此系统上运行脚本）</span></span>
<span class="line"><span>CategoryInfo : SecurityError ...</span></span>
<span class="line"><span>FullyQualifiedErrorId : UnauthorizedAccess</span></span></code></pre></div><p>本机中文系统，真实错误信息是中文；其中的 <code>UnauthorizedAccess</code> 就是遇到执行策略拦截时的错误标识。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ol><li>打开 PowerShell（开始菜单搜 &quot;PowerShell&quot;），输入 <code>$PSVersionTable</code>，记下 <code>PSVersion</code> 与 <code>PSEdition</code>。5.1 显示 <code>Desktop</code>，7 显示 <code>Core</code>。</li><li>按&quot;逐步例子&quot;建三个文件，依次运行例 1 ~ 8，对照输出。可用：</li></ol><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$lab </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Join-Path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TEMP </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;pslab&#39;</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">New-Item</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ItemType Directory $lab </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> Out-Null</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Set-Content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Join-Path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $lab </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;a.log&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;x&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Set-Content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Join-Path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $lab </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;b.log&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;x&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Set-Content</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Join-Path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $lab </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;c.txt&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) (</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;x&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> *</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 500</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Set-Location</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $lab</span></span></code></pre></div><ol start="3"><li>做完后清理：<code>Set-Location $env:TEMP; Remove-Item $lab -Recurse -Force</code>。</li><li>自己写：列出 <code>C:\\Windows</code> 下大于 1MB 的<strong>文件</strong>，按大小倒序取前 5 个（提示：<code>Get-ChildItem C:\\Windows -File</code>，<code>1MB</code> 是内置常量，可能有无权限的错误，加 <code>-ErrorAction SilentlyContinue</code>）。</li><li>用 <code>Get-Command *process*</code>、<code>Get-Help Get-Process -Examples</code> 学会自己查命令。</li><li>执行策略：用 <code>Get-ExecutionPolicy -List</code> 查看当前设置。想让当前用户能运行自己写的脚本：<code>Set-ExecutionPolicy RemoteSigned -Scope CurrentUser</code>（只影响你自己，不需要管理员）。</li></ol><h2 id="常见坑与排查" tabindex="-1">常见坑与排查 <a class="header-anchor" href="#常见坑与排查" aria-label="Permalink to &quot;常见坑与排查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>原因与办法</th></tr></thead><tbody><tr><td>运行 <code>.ps1</code> 报&quot;禁止运行脚本&quot;</td><td>执行策略为 <code>Restricted</code>。用 <code>Set-ExecutionPolicy RemoteSigned -Scope CurrentUser</code>；不要图省事用 <code>Bypass</code></td></tr><tr><td>从网上下载的脚本被拦截</td><td>文件带有&quot;来自互联网&quot;标记，RemoteSigned 要求签名。确认来源可信后用 <code>Unblock-File 脚本.ps1</code>。注意：先读懂脚本内容再运行</td></tr><tr><td><code>ls -l</code>、<code>rm -rf</code> 报错</td><td>那只是别名，参数不同。<code>rm -rf</code> 对应 <code>Remove-Item -Recurse -Force</code></td></tr><tr><td>5.1 里用 <code>Get-Content</code>/<code>Set-Content</code> 改含中文的 UTF-8 文件后乱码</td><td>5.1 默认用系统 ANSI 代码页（本机是 GBK）读写。我实测：<code>Set-Content -Encoding UTF8</code> 在 5.1 写出的文件<strong>带 BOM</strong>（开头多 <code>EF BB BF</code> 三字节），这又会让某些工具出问题。处理含中文的文件用专门的编辑工具，或显式指定编码</td></tr><tr><td><code>&amp;&amp;</code> 在 5.1 里报语法错误</td><td>5.1 不支持 <code>&amp;&amp;</code>/<code>||</code>（7 才支持）。用 <code>A; if ($?) { B }</code></td></tr><tr><td><code>$_</code> 在代码块外是空的</td><td><code>$_</code> 只在 <code>Where-Object</code>、<code>ForEach-Object</code> 等的 <code>{ }</code> 里有意义</td></tr><tr><td>输出被截断成 <code>...</code></td><td>表格列太宽被省略。用 <code>Format-Table -AutoSize</code>、<code>Format-List</code>，或 <code>Select-Object *</code> 看全部属性</td></tr><tr><td>对象变成了字符串，没法再取属性</td><td>管道中间用了 <code>Out-String</code>、<code>Format-*</code>。<code>Format-*</code> 应放在管道<strong>最后</strong>，它输出的是给人看的格式而不是数据对象</td></tr><tr><td><code>&quot;5&quot; + 1</code> 和 <code>5 + &quot;1&quot;</code> 结果不同</td><td>本机实测：<code>&quot;5&quot; + 1</code> 得到字符串 <code>51</code>，<code>5 + &quot;1&quot;</code> 得到数字 <code>6</code>——<strong>运算结果类型由左边操作数决定</strong>。不确定时显式转换 <code>[int]&quot;5&quot; + 1</code></td></tr><tr><td><code>curl.exe</code> 访问 <code>localhost</code> 返回 503</td><td>本机设了代理环境变量 <code>HTTP_PROXY</code>（本机实测值为 <code>http://127.0.0.1:38888</code>），curl 把请求转给代理了，加 <code>--noproxy &#39;*&#39;</code>。本机实测 5.1 的 <code>Invoke-RestMethod</code> 访问本机服务<strong>不受</strong>这个环境变量影响（它用的是系统代理设置而不是环境变量）。见 <a href="/Encyclopedia/50-工具与工程/环境变量与PATH">环境变量与PATH</a></td></tr></tbody></table><h2 id="练习题与答案" tabindex="-1">练习题与答案 <a class="header-anchor" href="#练习题与答案" aria-label="Permalink to &quot;练习题与答案&quot;">​</a></h2><p><strong>1.</strong> 写一条命令，找出当前目录下扩展名为 <code>.log</code> 的文件，只输出它们的名字。</p><p>答：<code>Get-ChildItem *.log | Select-Object -ExpandProperty Name</code>。</p><p><strong>2.</strong> <code>Get-Process | Where-Object { $_.WorkingSet64 -gt 500MB }</code> 的意思是？</p><p>答：筛选出占用物理内存超过 500MB 的进程。<code>$_</code> 是当前进程对象，<code>500MB</code> 是内置的 500×1024×1024。</p><p><strong>3.</strong> 为什么说 <code>Format-Table</code> 要放在管道最后？</p><p>答：它把对象转换成&quot;给人看的格式化对象&quot;，后面的命令就拿不到原来的属性了。</p><p><strong>4.</strong> 在 5.1 里想&quot;A 成功才执行 B&quot;，怎么写？</p><p>答：<code>A; if ($?) { B }</code>。<code>$?</code> 是上一条命令是否成功。</p><p><strong>5.</strong> 执行策略能阻止一个有恶意的人运行脚本吗？</p><p>答：不能。微软文档明确说它不是安全边界，只是防止用户无意中运行脚本的纵深防御措施。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PowerShell 命令叫 cmdlet（动词-名词），管道传递的是 <strong>.NET 对象</strong>，用 <code>Get-Member</code> 查看属性。</li><li>常用管道工具：<code>Where-Object</code> 筛选、<code>Select-Object</code> 取列、<code>Sort-Object</code> 排序、<code>Group-Object</code> 分组、<code>Measure-Object</code> 统计、<code>ForEach-Object</code> 循环；<code>$_</code> 是当前对象。</li><li>比较用 <code>-eq -gt -like</code> 等；<code>-ErrorAction Stop</code> + <code>try/catch</code> 处理错误。</li><li>执行策略控制脚本能否运行，不是安全边界；用 <code>RemoteSigned -Scope CurrentUser</code> 即可满足个人开发。</li><li>5.1（<code>powershell.exe</code>，自带）与 7（<code>pwsh.exe</code>，需安装，可并存）并存，语法特性有差异。</li></ul><h2 id="相关词条" tabindex="-1">相关词条 <a class="header-anchor" href="#相关词条" aria-label="Permalink to &quot;相关词条&quot;">​</a></h2><p><a href="/Encyclopedia/50-工具与工程/命令行与Linux">命令行与Linux</a>、<a href="/Encyclopedia/50-工具与工程/环境变量与PATH">环境变量与PATH</a>、<a href="/Encyclopedia/50-工具与工程/JSON-XML-YAML">JSON-XML-YAML</a>、<a href="/Encyclopedia/20-编程语言/CSharp/CSharp类型与变量">CSharp类型与变量</a>、<a href="/Encyclopedia/10-计算机基础/操作系统/操作系统">操作系统</a>、<a href="/Encyclopedia/50-工具与工程/Git/Git">Git</a></p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li>PowerShell 官方文档总览：<a href="https://learn.microsoft.com/en-us/powershell/scripting/overview" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/powershell/scripting/overview</a></li><li>Windows PowerShell 5.1 与 PowerShell 7 的差异：<a href="https://learn.microsoft.com/en-us/powershell/scripting/whats-new/differences-from-windows-powershell" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/powershell/scripting/whats-new/differences-from-windows-powershell</a></li><li>about_Execution_Policies：<a href="https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_execution_policies" target="_blank" rel="noreferrer">https://learn.microsoft.com/en-us/powershell/module/microsoft.powershell.core/about/about_execution_policies</a></li></ul>`,93)])])}const u=t(n,[["render",d]]);export{g as __pageData,u as default};
